-- #185 작성 제한 (ADR-0069 decision 2 #45-12, #45-14, decision 3 #37-9, decision 4 #185 rows;
-- ADR-0082). Generated by `drizzle-kit generate`, then hand-edited where marked: this header and the
-- tail. The snapshot is as generated. Self-contained and additive on #50's 0038: no row changes.
--
-- - moderation_actions.type: `writing_restriction` joins the list (the CHECK replaced, as ADR-0081
--   left it for #185 — a varchar, so the batch that adds the type could use it).
-- - moderation_actions_subject_check: a writing restriction names one of the member's post or
--   comment at most (the item whose pending reports it resolved), as a warning.
-- - moderation_actions_ends_at_check: a writing restriction's end — its time and the term picked,
--   null for 무기한 — never before its own time; every other type keeps none.
-- - moderation_actions_standing_restriction_idx: a member's writing restrictions not cancelled,
--   which every post, comment and edit and every new value of a public profile item asks.
-- - restriction_end_changes: an operator bringing a writing restriction's end forward, a
--   shortening (감경) or an early lift (조기 해제), with the end before and after, the reason and
--   who and when.
CREATE TABLE "restriction_end_changes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"action_id" uuid NOT NULL,
	"kind" varchar(16) NOT NULL,
	"previous_ends_at" timestamp (3) with time zone,
	"ends_at" timestamp (3) with time zone NOT NULL,
	"reason" varchar(500) NOT NULL,
	"created_by" text NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "restriction_end_changes_kind_check" CHECK ("restriction_end_changes"."kind" IN ('shorten', 'lift')),
	CONSTRAINT "restriction_end_changes_reason_check" CHECK (btrim("restriction_end_changes"."reason") <> ''),
	CONSTRAINT "restriction_end_changes_earlier_check" CHECK ("restriction_end_changes"."previous_ends_at" IS NULL OR "restriction_end_changes"."ends_at" < "restriction_end_changes"."previous_ends_at")
);
