-- Hand-edited: an action is the record the member and operators read, and only its cancellation was
-- written after it (migration 0038). A writing restriction's end opens here: an operator brings it
-- forward while it stands (감경 and 조기 해제, #45-12 and #45-14) — never back, never to 무기한, never
-- once the restriction ended, never to before now (at the millisecond the column keeps: a lift is
-- the database clock's now, rounded) and never together with a cancellation. Each change is a
-- `restriction_end_changes` row the same transaction writes. The rest of the row stays as it was
-- given. DELETE stays for #184.
CREATE OR REPLACE FUNCTION moderation_actions_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.cancelled_at IS NOT NULL THEN
    RAISE EXCEPTION 'moderation action % was cancelled and cannot change', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF (NEW.id, NEW.type, NEW.user_id, NEW.post_id, NEW.comment_id, NEW.reason, NEW.note,
      NEW.created_by, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.type, OLD.user_id, OLD.post_id, OLD.comment_id, OLD.reason, OLD.note,
      OLD.created_by, OLD.created_at) THEN
    RAISE EXCEPTION 'moderation action % cannot change what was done', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.ends_at IS DISTINCT FROM OLD.ends_at THEN
    IF OLD.type <> 'writing_restriction'
       OR NEW.ends_at IS NULL
       OR NEW.ends_at < date_trunc('milliseconds', now())
       OR (OLD.ends_at IS NOT NULL AND (NEW.ends_at >= OLD.ends_at OR OLD.ends_at <= now()))
       OR NEW.cancelled_at IS NOT NULL THEN
      RAISE EXCEPTION 'moderation action % only brings a standing restriction''s end forward', OLD.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
-- Hand-edited: a change of a restriction's end is kept as it was made, never rewritten. buddha_app
-- keeps SELECT/INSERT/DELETE of the default privileges in docker/postgres/init/01-roles.sql (DELETE
-- for #184) and loses UPDATE.
REVOKE UPDATE ON TABLE "restriction_end_changes" FROM buddha_app;
